def calculate_discount(qty, is_vip, subtotal):
    pct = 0.15 if qty >= 3 else 0.0
    if is_vip:
        pct += 0.05
    pct = min(pct, 0.30)          # cap
    return round(subtotal * pct, 2)

# unit tests: fast, precise, no browser
def test_bulk_vip_is_capped():
    assert calculate_discount(5, True, 100.00) == 20.00

def test_cap_never_exceeds_30():
    # even if rules stack past 30%, result is capped
    assert calculate_discount(50, True, 200.00) <= 200.00 * 0.30

def price(cart_total, has_loyalty):
    tier = 0.15 if cart_total >= 250 else 0.10 if cart_total >= 100 else 0.0
    subtotal = cart_total * (1 - tier)
    return round(subtotal * 0.95, 2) if has_loyalty else round(subtotal, 2)

def test_tier_boundaries():
    assert price(99.99, False) == 99.99   # below first tier
    assert price(100.00, False) == 90.00  # exactly hits 10%
    assert price(250.00, False) == 212.50 # exactly hits 15%

def test_loyalty_stacks_after_tier():
    assert price(300.00, True) == 242.25  # 15% then 5% loyalty

