def save_order(order):
    old_store.write(order)          # old stays authoritative
    try:
        new_store.write(order)      # dual-write; failures must not
    except Exception as e:          # break the live write path
        metrics.incr("dualwrite.new_fail")
        log.warning("new-store write failed", err=e)

def read_order(order_id):
    if flags.enabled("reads_from_new", order_id):  # per-slice flip
        return new_store.read(order_id)
    return old_store.read(order_id)                # cheap revert = flag off
